// Builds ui/vendor/pierre-diffs.js from @pierre/diffs 1.5.2 (Apache-2.0): its file-name-to-language
// table, the language lookup T3 Code's diffs color with, and the sprite symbols its file headers and
// hunk separators draw. In a scratch folder `npm pack @pierre/diffs@1.5.2 && tar xzf pierre-diffs-1.5.2.tgz`,
// then `node scripts/vendor/pierre-diffs.mjs <scratch>/package`.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const pkg = process.argv[2];
if (!pkg) throw new Error("usage: node scripts/vendor/pierre-diffs.mjs <@pierre/diffs package folder>");
const { version } = JSON.parse(fs.readFileSync(path.join(pkg, "package.json"), "utf8"));
const source = fs.readFileSync(path.join(pkg, "dist/utils/getFiletypeFromFileName.js"), "utf8");
const table = source.match(/const EXTENSION_TO_FILE_FORMAT = (\{[\s\S]*?\n\});/)[1];
const extensions = new Function(`return ${table}`)();
const sprite = fs.readFileSync(path.join(pkg, "dist/sprite.js"), "utf8");
const SYMBOLS = ["diffs-icon-symbol-added", "diffs-icon-symbol-deleted", "diffs-icon-symbol-modified", "diffs-icon-symbol-moved", "diffs-icon-expand", "diffs-icon-expand-all", "diffs-icon-arrow-right-short"];
const symbols = SYMBOLS.map((id) => {
  const m = sprite.match(new RegExp(`<symbol id="${id}"[\\s\\S]*?</symbol>`));
  if (!m) throw new Error(`no ${id} in the sprite`);
  return m[0].replace(/\n\s*/g, "");
});

const out = `// @pierre/diffs ${version} (Apache-2.0, https://github.com/pierrecomputer/pierre): the language each file
// name is colored as (utils/getFiletypeFromFileName.js) and the sprite symbols of its file headers and
// hunk separators (sprite.js). Generated by scripts/vendor/pierre-diffs.mjs; don't edit by hand.
const PIERRE_DIFFS = (() => {
  const extensions = ${JSON.stringify(extensions)};
  const match = (name) => {
    if (Object.hasOwn(extensions, name)) return extensions[name] ?? null;
    const compound = name.match(/\\.([^/\\\\]+\\.[^/\\\\]+)$/);
    if (compound && Object.hasOwn(extensions, compound[1])) return extensions[compound[1]] ?? "text";
    const simple = name.match(/\\.([^.]+)$/)?.[1] ?? "";
    return Object.hasOwn(extensions, simple) ? extensions[simple] ?? "text" : null;
  };
  /** getFiletypeFromFileName: a Shiki language name, or "text". */
  const filetype = (fileName) => {
    const format = match(fileName);
    if (format != null) return format;
    const base = fileName.split(/[/\\\\]/).pop() ?? fileName;
    return base === fileName ? "text" : match(base) ?? "text";
  };
  const sprite = ${JSON.stringify(`<svg data-icon-sprite aria-hidden="true" width="0" height="0">${symbols.join("")}</svg>`)};
  return { filetype, sprite };
})();
`;
const dest = path.join(path.dirname(fileURLToPath(import.meta.url)), "../../ui/vendor/pierre-diffs.js");
fs.writeFileSync(dest, out);
console.log(`${dest}: ${Object.keys(extensions).length} file names, ${symbols.length} symbols`);
